from fastapi import FastAPI, Depends, HTTPException, Security
from fastapi.security import APIKeyQuery, APIKeyHeader, APIKeyCookie, HTTPBearer, HTTPDigest, OpenIdConnect
from fastapi.testclient import TestClient

app = FastAPI()

api_key_query = APIKeyQuery(name="query_key")
api_key_header = APIKeyHeader(name="header_key")
api_key_cookie = APIKeyCookie(name="cookie_key")
http_bearer = HTTPBearer()
http_digest = HTTPDigest()
oidc = OpenIdConnect()

@app.get("/query")
def read_query(key: str = Security(api_key_query)):
    return {"key": key}

@app.get("/header")
def read_header(key: str = Security(api_key_header)):
    return {"key": key}

@app.get("/cookie")
def read_cookie(key: str = Security(api_key_cookie)):
    return {"key": key}

@app.get("/bearer")
def read_bearer(token: str = Security(http_bearer)):
    return {"token": token}

@app.get("/digest")
def read_digest(token: str = Security(http_digest)):
    return {"token": token}

@app.get("/oidc")
def read_oidc(token: str = Security(oidc)):
    return {"token": token}

client = TestClient(app)

schemes = [
    ("/query", "APIKeyQuery"),
    ("/header", "APIKeyHeader"),
    ("/cookie", "APIKeyCookie"),
    ("/bearer", "HTTPBearer"),
    ("/digest", "HTTPDigest"),
    ("/oidc", "OpenIdConnect"),
]

for path, name in schemes:
    response = client.get(path)
    print(f"{name}: status={response.status_code}, headers={response.headers.get(\"WWW-Authenticate\")}")
' 2>&1 | tee /tmp/repro_out.txt; cat > /tmp/ctx.md << 'CTX'
